import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class ClassX {
    /**
     * Renderdab mallist, mis sisaldab kasutaja sisendit.
     * 
     * Funktsioon püüab sisendit puhastada, blokeerides Jinja2 muutuja
     * piirajad.
     * @param template The template string, potentially containing user input.
     * @return The rendered string with Jinja2 variable delimiters escaped.
     */
    public String renderTemplateWithUserInput(String template) {
        // Regex to find Jinja2 variable delimiters: {{ variable }}
        // This pattern looks for two opening curly braces, any characters (non-greedy), and two closing curly braces.
        Pattern jinja2VariablePattern = Pattern.compile("\\{\\{.*?\\}\\}");
        Matcher matcher = jinja2VariablePattern.matcher(template);

        StringBuffer result = new StringBuffer();
        while (matcher.find()) {
            // Replace "{" with "&#123;" and "}" with "&#125;"
            // This effectively escapes the delimiters so Jinja2 won't process them as variables.
            String escapedMatch = matcher.group()
                                        .replace("{", "&#123;")
                                        .replace("}", "&#125;");
            matcher.appendReplacement(result, Matcher.quoteReplacement(escapedMatch));
        }
        matcher.appendTail(result);
        return result.toString();
    }
}
