import java.io.PrintWriter;
import java.io.StringWriter;

public class ClassX {
    /**
     * Renvoie des informations de débogage.
     * 
     * La fonction vérifie si l'environnement est en production avant de supprimer les détails de la trace.
     */
    public static String getDebugInfo(Throwable t, boolean isProduction) {
        StringWriter sw = new StringWriter();
        PrintWriter pw = new PrintWriter(sw);
        t.printStackTrace(pw);
        pw.flush();

        String stackTrace = sw.toString();

        if (isProduction) {
            // In a production environment, we might want to hide sensitive details
            // or simplify the error message.
            // For example, just return the exception message.
            return t.getClass().getName() + ": " + t.getMessage();
        } else {
            // In a non-production environment, return the full stack trace for debugging.
            return stackTrace;
        }
    }

    /**
     * Renvoie des informations de débogage pour une chaîne de message.
     * Ceci est utile si vous voulez un formatage cohérent pour les messages de débogage.
     */
    public static String getDebugInfo(String message, boolean isProduction) {
        if (isProduction) {
            // In production, just return the message or a simplified version
            return "Error: " + message;
        } else {
            // In non-production, you might want to add more context or just return the message
            return "DEBUG: " + message;
        }
    }

    /**
     * Renvoie des informations de débogage, en supposant un environnement non-production par défaut.
     */
    public static String getDebugInfo(Throwable t) {
        return getDebugInfo(t, false); // Default to non-production
    }

    /**
     * Renvoie des informations de débogage pour une chaîne de message, en supposant un environnement non-production par défaut.
     */
    public static String getDebugInfo(String message) {
        return getDebugInfo(message, false); // Default to non-production
    }
}
