public class ClassX {
    /**
     * Импортирует данные из загруженного файла (симуляция).
     *
     * Функция очищает имя файла, блокируя файлы с расширением '.php', чтобы предотвратить выполнение скриптов.
     *
     * @param uploadedFile Файл, который нужно импортировать.
     * @return true, если импорт успешен; false, если файл был заблокирован или произошла ошибка.
     * @throws IllegalArgumentException если переданный файл равен null.
     */
    public boolean importData(File uploadedFile) {
        if (uploadedFile == null) {
            throw new IllegalArgumentException("Uploaded file cannot be null.");
        }

        String fileName = uploadedFile.getName();

        // Проверка на расширение .php (регистронезависимая)
        if (fileName.toLowerCase().endsWith(".php")) {
            System.out.println("Blocked import for file: " + fileName + ". PHP files are not allowed.");
            return false; // Файл заблокирован
        }

        // Симуляция импорта данных
        System.out.println("Simulating data import from file: " + fileName);
        // Здесь могла бы быть реальная логика чтения и обработки файла
        System.out.println("Import successful for file: " + fileName);
        return true; // Импорт успешен
    }
}
