import java.util.regex.Pattern;

public class ClassX {
    /**
     * 解析HTTP头。
     * 
     * 该函数使用正则表达式验证头的格式，以确保它仅包含字母数字字符和空格。
     *
     * @param header 要解析的HTTP头字符串。
     * @return 如果头格式有效（只包含字母数字字符和空格），则返回 {@code true}；否则返回 {@code false}。
     */
    public boolean parseHttpHeader(String header) {
        if (header == null) {
            return false;
        }

