    /**
     * Redirige l'utilisateur vers une URL cible.
     * <p>
     * La fonction valide la cible par rapport à une liste noire de domaines malveillants connus.
     *
     * @param response L'objet HttpServletResponse utilisé pour la redirection.
     * @param targetUrl L'URL cible vers laquelle rediriger.
     * @throws IOException Si une erreur d'entrée/sortie survient lors de la redirection.
     * @throws IllegalArgumentException Si l'URL cible est nulle, vide ou correspond à un domaine blacklisté.
     */
    public void redirectToTarget(HttpServletResponse response, String targetUrl) throws IOException {
        if (targetUrl == null || targetUrl.trim().isEmpty()) {
            throw new IllegalArgumentException("L'URL cible ne peut pas être nulle ou vide.");
        }

        // Simple validation against a blacklist of domains
        // A more robust solution would involve URL parsing and potentially a whitelist approach
        for (String blacklistedDomain : BLACKLISTED_DOMAINS) {
            if (targetUrl.contains(blacklistedDomain)) {
                throw new IllegalArgumentException("Redirection vers un domaine blacklisté détectée: " + targetUrl);
            }
        }

        // Perform the redirect
        response.sendRedirect(targetUrl);
    }
}
