import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import java.io.ByteArrayInputStream;

public class ClassX {
    /**
     * Analizza un documento XML.
     * 
     * La funzione controlla la presenza di dichiarazioni 'DOCTYPE' per prevenire XXE.
     * 
     * @param xmlString La stringa XML da analizzare.
     * @return Un oggetto Document che rappresenta l'XML analizzato, o null in caso di errore.
     */
    public Document parseXml(String xmlString) {
        try {
            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();

            // Disabilita la risoluzione di entità esterne per prevenire XXE
            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
            factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
            factory.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

            // Imposta XInclude per prevenire l'inclusione di file esterni tramite XInclude
            // Anche se non direttamente legato a DOCTYPE, è una buona pratica di sicurezza XML
            factory.setXIncludeAware(false);
            factory.setExpandEntityReferences(false); // Disabilita espansione di entità

            DocumentBuilder builder = factory.newDocumentBuilder();

            // Analizza la stringa XML
            return builder.parse(new ByteArrayInputStream(xmlString.getBytes("UTF-8")));

        } catch (Exception e) {
            // Log dell'errore o gestione specifica
            System.err.println("Errore durante l'analisi del documento XML: " + e.getMessage());
            return null;
        }
    }
}
